import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
// ----------------------------------------------------------------------------
// ZOD SCHEMA
// ----------------------------------------------------------------------------


export type CuteRotatingGlobeProps = Record<string, any>;

// ----------------------------------------------------------------------------
// SUB-COMPONENTS
// ----------------------------------------------------------------------------

const Cloud: React.FC<{ x: number; y: number; delay: number; scale: number; color: string }> = ({ 
  x, y, delay, scale, color 
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  
  // Entrance spring animation
  const appearScale = spring({ 
    frame: frame - delay, 
    fps, 
    config: { damping: 12, mass: 0.8 } 
  });
  
  // Gentle floating effect
  const floatY = Math.sin((frame + delay) / 20) * 12;

  return (
    <div style={{
      position: 'absolute', 
      left: x, 
      top: y,
      transform: `translateY(${floatY}px) scale(${appearScale * scale})`,
      opacity: appearScale > 0 ? 1 : 0,
      pointerEvents: "none",
    }}>
      <div style={{ position: 'relative', width: 140, height: 50 }}>
        {/* Cloud Base */}
        <div style={{ 
          position: 'absolute', bottom: 0, width: 140, height: 50, 
          borderRadius: 25, backgroundColor: color 
        }} />
        {/* Cloud Puffs */}
        <div style={{ 
          position: 'absolute', bottom: 15, left: 20, width: 60, height: 60, 
          borderRadius: 30, backgroundColor: color 
        }} />
        <div style={{ 
          position: 'absolute', bottom: 15, left: 65, width: 50, height: 50, 
          borderRadius: 25, backgroundColor: color 
        }} />
        <div style={{ 
          position: 'absolute', bottom: 10, left: 100, width: 30, height: 30, 
          borderRadius: 15, backgroundColor: color 
        }} />
      </div>
    </div>
  );
};

const Sparkle: React.FC<{ x: number; y: number; delay: number; scaleBase: number; color: string }> = ({ 
  x, y, delay, scaleBase, color 
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  
  // Entrance spring animation
  const appearScale = spring({ 
    frame: frame - delay, 
    fps, 
    config: { damping: 10 } 
  });

  // Twinkling effect (scaling up and down slightly)
  const twinkle = interpolate(
    Math.sin((frame + delay * 15) / 12),
    [-1, 1],
    [0.6, 1.2]
  );

  // Slow rotation
  const rotation = (frame + delay) * 0.8;

  return (
    <div style={{
      position: 'absolute', 
      left: x, 
      top: y,
      transform: `scale(${appearScale * scaleBase * twinkle}) rotate(${rotation}deg)`,
      width: 45, height: 45,
      color: color,
      pointerEvents: "none",
    }}>
      <svg viewBox="0 0 100 100" style={{ width: '100%', height: '100%', overflow: 'visible' }}>
        <path 
          d="M 50 0 C 50 40 60 50 100 50 C 60 50 50 60 50 100 C 50 60 40 50 0 50 C 40 50 50 40 50 0" 
          fill="currentColor" 
        />
      </svg>
    </div>
  );
};

const Continents: React.FC<{ size: number; color: string; offset: number }> = ({ size, color, offset }) => (
  <div style={{ position: "absolute", width: size, height: size, left: offset, top: 0 }}>
    {/* Cute stylized blobs representing landmasses */}
    <div style={{ position: "absolute", left: '8%', top: '22%', width: '28%', height: '45%', borderRadius: size, backgroundColor: color }} />
    <div style={{ position: "absolute", left: '18%', top: '55%', width: '18%', height: '30%', borderRadius: size, backgroundColor: color }} />
    <div style={{ position: "absolute", left: '46%', top: '15%', width: '25%', height: '58%', borderRadius: size, backgroundColor: color }} />
    <div style={{ position: "absolute", left: '76%', top: '30%', width: '28%', height: '42%', borderRadius: size, backgroundColor: color }} />
    <div style={{ position: "absolute", left: '88%', top: '68%', width: '14%', height: '18%', borderRadius: size, backgroundColor: color }} />
  </div>
);

// ----------------------------------------------------------------------------
// MAIN COMPONENT
// ----------------------------------------------------------------------------

const CuteRotatingGlobe: React.FC<CuteRotatingGlobeProps> = ({
  backgroundColor = "#1a1a2e",
  transparentBackground = false,
  durationInSeconds = 10,
  globeSize = 460,
  waterColor = "#4facfe",
  landColor = "#43e97b",
  cloudColor = "#ffffff",
  sparkleColor = "#ffea00",
  rotationSpeed = 1.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Globe animations
  const globeAppearScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.9 },
  });
  
  // Continuous rotation (panning effect)
  const panX = -((frame * rotationSpeed * 2) % globeSize);
  
  // Gentle overall bobbing
  const globeBobY = Math.sin(frame / 25) * 10;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* ---------------- BACKGROUND ELEMENTS ---------------- */}
      
      <Cloud x={width * 0.08} y={height * 0.18} delay={15} scale={1.1} color={cloudColor} />
      <Cloud x={width * 0.68} y={height * 0.12} delay={25} scale={0.85} color={cloudColor} />
      <Cloud x={width * 0.78} y={height * 0.75} delay={35} scale={1.3} color={cloudColor} />
      <Cloud x={width * 0.12} y={height * 0.68} delay={45} scale={0.9} color={cloudColor} />

      <Sparkle x={width * 0.22} y={height * 0.28} delay={10} scaleBase={1} color={sparkleColor} />
      <Sparkle x={width * 0.78} y={height * 0.38} delay={5} scaleBase={1.2} color={sparkleColor} />
      <Sparkle x={width * 0.18} y={height * 0.52} delay={30} scaleBase={0.7} color={sparkleColor} />
      <Sparkle x={width * 0.62} y={height * 0.82} delay={20} scaleBase={1.1} color={sparkleColor} />
      <Sparkle x={width * 0.85} y={height * 0.58} delay={40} scaleBase={0.9} color={sparkleColor} />


      {/* ---------------- CENTER GLOBE ---------------- */}
      
      <div style={{
        position: "absolute",
        left: width / 2 - globeSize / 2,
        top: height / 2 - globeSize / 2,
        width: globeSize,
        height: globeSize,
        borderRadius: "50%",
        backgroundColor: waterColor,
        overflow: "hidden",
        transform: `translateY(${globeBobY}px) scale(${globeAppearScale})`,
        // Outer glow/shadow for depth
        boxShadow: `0px 20px 40px rgba(0,0,0,0.2)`
      }}>
        
        {/* Panning Landmasses (Seamless Loop) */}
        <div style={{ 
          display: 'flex', 
          width: globeSize * 2, 
          height: '100%',
          transform: `translateX(${panX}px)`,
          transition: "none"
        }}>
          <Continents size={globeSize} color={landColor} offset={0} />
          <Continents size={globeSize} color={landColor} offset={globeSize} />
        </div>

        {/* 3D Sphere Inset Shadow Overlay */}
        <div style={{
          position: "absolute", 
          inset: 0, 
          borderRadius: "50%",
          boxShadow: `inset -${globeSize * 0.08}px -${globeSize * 0.08}px 0px 0px rgba(0,0,0,0.15), inset ${globeSize * 0.04}px ${globeSize * 0.04}px 0px 0px rgba(255,255,255,0.15)`,
          pointerEvents: "none"
        }} />

        {/* Glossy Curved Highlight */}
        <div style={{
          position: "absolute",
          top: globeSize * 0.08, 
          left: globeSize * 0.15,
          width: globeSize * 0.3, 
          height: globeSize * 0.12,
          borderRadius: "50%",
          backgroundColor: "#ffffff",
          opacity: 0.3,
          transform: "rotate(-30deg)",
          pointerEvents: "none"
        }} />
        
      </div>
    </AbsoluteFill>
  );
};

export default CuteRotatingGlobe;